// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface ChecklistItemOut {
  item_id: number;
  phase: "SignIn" | "TimeOut" | "SignOut";
  prompt: string;
  /** Confirm: answered Yes (or NotApplicable when allow_na); Question: Yes or No */
  kind: "Confirm" | "Question";
  allow_na: boolean;
  /** The answer that needs a note */
  note_when: "Yes" | "No" | null;
  reference: string | null;
  sort_order: number;
  is_active: boolean;
  row_version: number;
}

export interface ChecklistItemIn {
  phase: "SignIn" | "TimeOut" | "SignOut";
  prompt: string;
  kind?: "Confirm" | "Question";
  /** A confirmation that may not apply (Confirm only) */
  allow_na?: boolean;
  /** The answer that needs a note */
  note_when?: "Yes" | "No" | null;
  reference?: string | null;
  sort_order?: number;
}

export interface ChecklistItemUpdateIn {
  prompt?: string | null;
  kind?: "Confirm" | "Question" | null;
  allow_na?: boolean | null;
  note_when?: "Yes" | "No" | null;
  reference?: string | null;
  sort_order?: number | null;
  /** false: no longer asked (recorded pauses keep it) */
  is_active?: boolean | null;
  expected_version?: number | null;
}

export interface ClinicalPrivilegeOut {
  privilege_id: number;
  employee_id: number;
  full_name: string;
  designation: string;
  specialty: string | null;
  license_type: "PMDC" | "PNC" | "Other" | null;
  license_number: string | null;
  privilege: "Surgery" | "Anaesthesia" | "PreAnaesthesiaAssessment" | "RecoveryDischarge" | "Prescribing" | "RestrictedPrescribing" | "MedicationAdministration" | "RadiologyReporting";
  scope: string;
  basis: string;
  valid_from: string;
  valid_until: string | null;
  granted_by: number;
  granted_by_name: string;
  granted_at: string;
  revoked_at: string | null;
  revoked_by_name: string | null;
  revoke_reason: string | null;
  row_version: number;
  /** Not revoked and valid today: the signatures of the surgical record accept it */
  is_current: boolean;
}

/** The surgical safety checklist of the hospital — GET /api/v1/ot/checklist-items (who may call: holders of ot.clinical.view or ot.checklist.record or ot.checklist.configure). */
export function listChecklistItems(query?: { include_inactive?: boolean }): Promise<ChecklistItemOut[]> {
  return api<ChecklistItemOut[]>("GET", withQuery(`/ot/checklist-items`, query), undefined);
}

/** Add an item to the safety checklist — POST /api/v1/ot/checklist-items (who may call: holders of ot.checklist.configure). */
export function addChecklistItem(body: ChecklistItemIn): Promise<ChecklistItemOut> {
  return api<ChecklistItemOut>("POST", `/ot/checklist-items`, body, { idempotent: true });
}

/** Change or retire a safety checklist item — PATCH /api/v1/ot/checklist-items/{item_id} (who may call: holders of ot.checklist.configure). */
export function updateChecklistItem(item_id: number, body: ChecklistItemUpdateIn): Promise<ChecklistItemOut> {
  return api<ChecklistItemOut>("PATCH", `/ot/checklist-items/${item_id}`, body);
}

/** The written theatre policy as a PDF — GET /api/v1/ot/theatre-policy/pdf (who may call: holders of ot.clinical.view or ot.checklist.configure or ot.privilege.manage). */
export function theatrePolicyPdf(): Promise<unknown> {
  return api<unknown>("GET", `/ot/theatre-policy/pdf`, undefined);
}

/** The clinical privileges register — GET /api/v1/ot/privileges (who may call: holders of ot.status.view or ot.privilege.manage). */
export function listPrivileges(query?: { employee_id?: number | null; privilege?: "Surgery" | "Anaesthesia" | "PreAnaesthesiaAssessment" | "RecoveryDischarge" | "Prescribing" | "RestrictedPrescribing" | "MedicationAdministration" | "RadiologyReporting" | null; include_revoked?: boolean }): Promise<ClinicalPrivilegeOut[]> {
  return api<ClinicalPrivilegeOut[]>("GET", withQuery(`/ot/privileges`, query), undefined);
}
